CREATE SCHEMA IF NOT EXISTS billing;

CREATE TABLE IF NOT EXISTS billing.payment_terms (
    id UUID NOT NULL DEFAULT gen_random_uuid(),
    company_id UUID,
    name TEXT NOT NULL,
    note TEXT,
    sequence INTEGER NOT NULL DEFAULT 10,
    status payment_term_status NOT NULL DEFAULT 'active',
    early_discount BOOLEAN NOT NULL DEFAULT FALSE,
    discount_percent NUMERIC(7, 4) NOT NULL DEFAULT 0 CHECK (discount_percent >= 0),
    discount_days INTEGER NOT NULL DEFAULT 0,
    discount_account_id UUID,
    discount_tax_basis discount_tax_basis NOT NULL DEFAULT 'included',
    metadata JSONB NOT NULL DEFAULT '{"created_at":null,"updated_at":null,"deleted_at":null,"created_by":null,"updated_by":null,"deleted_by":null}'::jsonb,
    PRIMARY KEY (id)
);

CREATE INDEX IF NOT EXISTS idx_payment_terms_company_id_status ON billing.payment_terms (company_id, status);

-- GIN index for audit metadata JSONB queries
CREATE INDEX IF NOT EXISTS idx_payment_terms_metadata_gin ON billing.payment_terms USING GIN (metadata);
CREATE INDEX IF NOT EXISTS idx_payment_terms_metadata_deleted_at ON billing.payment_terms ((metadata->>'deleted_at'));
CREATE INDEX IF NOT EXISTS idx_payment_terms_metadata_created_at ON billing.payment_terms ((metadata->>'created_at'));
CREATE INDEX IF NOT EXISTS idx_payment_terms_metadata_updated_at ON billing.payment_terms ((metadata->>'updated_at'));

-- Triggers for automatic metadata timestamp management
-- Automatically sets created_at on INSERT and updated_at on UPDATE

-- Function to set metadata->'created_at' on INSERT
CREATE OR REPLACE FUNCTION billing.payment_terms_audit_timestamp() RETURNS trigger AS $$
BEGIN
    IF TG_OP = 'INSERT' THEN
        NEW.metadata = jsonb_set(NEW.metadata::jsonb, '{created_at}', to_jsonb(NOW()));
        NEW.metadata = jsonb_set(NEW.metadata::jsonb, '{updated_at}', to_jsonb(NOW()));
    ELSIF TG_OP = 'UPDATE' THEN
        NEW.metadata = jsonb_set(NEW.metadata::jsonb, '{updated_at}', to_jsonb(NOW()));
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

-- Trigger to set timestamps on INSERT
DROP TRIGGER IF EXISTS payment_terms_insert_audit ON billing.payment_terms;
CREATE TRIGGER payment_terms_insert_audit BEFORE INSERT ON billing.payment_terms
    FOR EACH ROW EXECUTE FUNCTION billing.payment_terms_audit_timestamp();

-- Trigger to set updated_at on UPDATE
DROP TRIGGER IF EXISTS payment_terms_update_audit ON billing.payment_terms;
CREATE TRIGGER payment_terms_update_audit BEFORE UPDATE ON billing.payment_terms
    FOR EACH ROW EXECUTE FUNCTION billing.payment_terms_audit_timestamp();
